pub fn format_cpp_float(value: f32) -> String {
    if value == 0.0 {
        return "0".to_string();
    }

    let mut text = format!("{value:.6}");
    while text.ends_with('0') {
        text.pop();
    }
    if text.ends_with('.') {
        text.pop();
    }

    text
}

