use std::collections::HashMap;
use std::hash::Hash;

use super::table_sizing::required_bucket_count;

const DEFAULT_MAX_LOAD_FACTOR: f32 = 0.875;

pub struct HopscotchMap<K, V> {
    // Store real entries so duplicate inserts keep the size stable.
    entries: HashMap<K, V>,
    bucket_count: usize,
    max_load_factor: f32,
}

impl<K, V> Default for HopscotchMap<K, V> {
    fn default() -> Self {
        Self {
            entries: HashMap::new(),
            bucket_count: 0,
            max_load_factor: DEFAULT_MAX_LOAD_FACTOR,
        }
    }
}

impl<K, V> HopscotchMap<K, V> {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn load_factor(&self) -> f32 {
        if self.bucket_count == 0 {
            0.0
        } else {
            self.entries.len() as f32 / self.bucket_count as f32
        }
    }

    pub fn max_load_factor(&mut self, value: f32) {
        self.max_load_factor = value;
    }

    pub fn rehash(&mut self, requested_buckets: usize) {
        self.bucket_count = required_bucket_count(
            self.entries.len(),
            self.max_load_factor,
            requested_buckets,
        );
    }
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn insert(&mut self, entry: (K, V)) -> Option<V> {
        let previous = self.entries.insert(entry.0, entry.1);
        if previous.is_none() {
            self.bucket_count = required_bucket_count(
                self.entries.len(),
                self.max_load_factor,
                self.bucket_count,
            );
        }
        previous
    }
}
